// Generated by gravitee-ai. Do not edit directly.
// Edit the source in the hub (tooling/cli/src/lib/checker/verify-ai-context.mjs) and re-run: gbuddy setup
//
// Offline verification that this repository's generated AI context matches its
// record (.ai/generated.yaml). Needs only Node and git: no npm install, no
// network, safe on fork pull requests. Errors block; warnings never do.
//
// Usage: node .github/scripts/verify-ai-context.mjs [--orphan-exclude <path-prefix>]...
import { createHash } from "node:crypto";
import { closeSync, existsSync, lstatSync, openSync, readFileSync, readSync, realpathSync } from "node:fs";
import { spawnSync } from "node:child_process";
import { join, sep } from "node:path";

const RECORD_PATH = ".ai/generated.yaml";
const MANIFEST_PATH = ".ai/manifest.yaml";
// Byte-identical to the hub's provenance constant; the hub pins the agreement in its test suite.
const MARKER = "Generated by gravitee-ai. Do not edit directly.";
const MD_HEADER_PREFIX = "<!--\n" + MARKER + "\n";
const JS_HEADER_PREFIX = "// " + MARKER + "\n";
const REMEDY = "run gbuddy setup, or ask a maintainer to regenerate on this branch";
// gbuddy setup itself refuses on a corrupt record, so the remedy for a parse
// failure is the record module's recovery, never a command that fails.
const PARSE_REMEDY = `delete ${RECORD_PATH} and re-run gbuddy setup (generated files re-adopt; team files stay refused), or ask a maintainer to regenerate on this branch`;

const errors = [];
const warnings = [];
const ABORT = Symbol("abort");

try {
  main();
} catch (error) {
  if (error !== ABORT) throw error;
}
report();

function main() {
  const excludes = parseArgs(process.argv.slice(2));
  const repoRoot = resolveRepoRoot();

  // Part 1: the record exists and its integrity line matches its body.
  const recordAbsolute = join(repoRoot, RECORD_PATH);
  if (!existsSync(recordAbsolute)) {
    fail(
      `${RECORD_PATH}: no generated-files record found; it is a committed file, so its absence is drift - ${REMEDY}`,
    );
  }
  let record;
  try {
    record = parseRecord(readFileSync(recordAbsolute, "utf8"));
  } catch (cause) {
    fail(`${RECORD_PATH}: ${cause.message}; ${PARSE_REMEDY}`);
  }

  const committedEntries = record.entries.filter(
    (entry) => entry.scope === "committed" && entry.status === "generated",
  );

  // Part 2: every committed entry's bytes match its recorded fingerprint.
  // Skipped-unmanaged entries record the intended bytes of a file setup refused
  // to overwrite; their mismatch is the standing advisory, never an error.
  for (const entry of record.entries) {
    if (entry.status === "skipped-unmanaged") {
      warnings.push(`${entry.path}: unmanaged and skipped at the last setup run; its generated content is not live`);
      continue;
    }
    if (entry.scope !== "committed") continue;
    if (badRecordPath(entry.path)) {
      errors.push(`${entry.path}: record entry path is not repo-relative; ${RECORD_PATH} was altered`);
      continue;
    }
    const absolute = join(repoRoot, entry.path);
    if (!existsSync(absolute)) {
      errors.push(`${entry.path}: missing committed file recorded as generated; ${REMEDY}`);
      continue;
    }
    if (!resolvesInside(repoRoot, absolute)) {
      errors.push(`${entry.path}: resolves outside the repository; ${RECORD_PATH} was altered`);
      continue;
    }
    let disk;
    try {
      disk = readFileSync(absolute);
    } catch {
      errors.push(`${entry.path}: cannot be read to verify its fingerprint; ${REMEDY}`);
      continue;
    }
    if (sha256(disk) !== entry.hash) {
      errors.push(
        `${entry.path}: does not match the record (hand edit, a formatter that rewrote it, or a checkout that rewrote line endings); ${REMEDY}`,
      );
    }
  }

  // Parts 3-5 need git; without it they are skipped behind one clear error.
  const tracked = gitTrackedFiles(repoRoot);
  if (tracked !== null) {
    // Part 3: no committed entry may be matched by an ignore rule. A
    // tracked-but-ignored file works today and silently drops on the next
    // delete-and-regenerate cycle.
    for (const path of gitIgnoredAmong(
      repoRoot,
      committedEntries.map((entry) => entry.path),
    )) {
      errors.push(
        `${path}: committed output is matched by an ignore rule; add a negation (!${path}) to .gitignore so it cannot silently drop`,
      );
    }

    // Membership is case-folded on both sides: two spellings are one file on
    // case-insensitive filesystems, matching the hub's own membership tests.
    const trackedFolded = new Set([...tracked].map((path) => path.toLowerCase()));
    const recordedFolded = new Set(record.entries.map((entry) => entry.path.toLowerCase()));

    // Part 4: a local-scope entry tracked in git means the record mislabels it
    // and tamper detection silently does not apply.
    for (const entry of record.entries) {
      if (entry.scope === "local" && trackedFolded.has(entry.path.toLowerCase())) {
        errors.push(
          `${entry.path}: recorded as a local per-machine file but tracked in git; the record mislabels it - ${REMEDY}`,
        );
      }
    }

    // Part 5: a tracked file carrying the exact generated-by header but absent
    // from the record is an orphan a hub version renamed or dropped. Exact
    // header match per file type, never substring: a file quoting the sentence
    // must survive. The extension filter is pinned to the set setup can emit
    // as committed text outputs (a test in the hub asserts this stays true).
    // The record itself cannot list itself and is exempt; the explicit clause
    // is defence in depth, since the extension filter already excludes .yaml.
    for (const path of tracked) {
      if (!path.endsWith(".md") && !path.endsWith(".mjs")) continue;
      if (path === RECORD_PATH || recordedFolded.has(path.toLowerCase())) continue;
      if (excludes.some((prefix) => path === prefix || path.startsWith(prefix + "/"))) continue;
      const absolute = join(repoRoot, path);
      // Never follow a symlink: a generated output is never a symlink
      // (reconcile refuses them), and following one can read outside the
      // repository or block forever on a FIFO target.
      let stat;
      try {
        stat = lstatSync(absolute);
      } catch {
        continue;
      }
      if (!stat.isFile()) continue;
      if (!hasGeneratedHeader(headOf(absolute))) continue;
      errors.push(
        `${path}: carries the generated-by header but is absent from the record; delete it if a hub version no longer generates it, or ${REMEDY}`,
      );
    }
  }

  // Part 6: re-verify the generator's recorded inputs. Drift is a warning: the
  // committed outputs still match what they were generated from. Degradation
  // mirrors gbuddy check: unreadable counts as drift; a path resolving outside
  // the repository is warned about and never read.
  for (const input of record.inputs ?? []) {
    if (badRecordPath(input.path)) {
      errors.push(`${input.path}: record input path is not repo-relative; ${RECORD_PATH} was altered`);
      continue;
    }
    const absolute = join(repoRoot, input.path);
    if (existsSync(absolute) && !resolvesInside(repoRoot, absolute)) {
      if ("hash" in input) {
        warnings.push(`${input.path}: resolves outside the repository; cannot be verified as an input`);
      }
      continue;
    }
    let drifted;
    if ("hash" in input) {
      try {
        drifted = !existsSync(absolute) || sha256(readFileSync(absolute)) !== input.hash;
      } catch {
        drifted = true;
      }
    } else {
      drifted = existsSync(absolute) !== input.present;
    }
    if (drifted) {
      warnings.push(`${input.path}: changed since the last setup run; run gbuddy setup and commit the result`);
    }
  }

  // Part 7: the generating version against the manifest's pin. Gated on a pin
  // existing so a pre-pin repository (and the hub itself) stays quiet; dormant
  // on records that predate the generatedBy field.
  const pin = readPin(repoRoot);
  if (pin !== null && record.generatedBy !== undefined && record.generatedBy !== pin) {
    if (record.generatedBy === "checkout") {
      warnings.push(
        `${RECORD_PATH}: generated from a working-tree checkout while the manifest pins ${pin}; regenerate with the pinned release`,
      );
    } else {
      warnings.push(
        `${RECORD_PATH}: generated by ${record.generatedBy} but the manifest pins ${pin}; regenerate with the pinned release`,
      );
    }
  }
}

/** The repository root from git when available, so the script works from any subdirectory. */
function resolveRepoRoot() {
  const result = spawnSync("git", ["rev-parse", "--show-toplevel"], { cwd: process.cwd(), encoding: "utf8" });
  if (!result.error && result.status === 0) {
    const top = result.stdout.trim();
    if (top !== "") return realpathSync(top);
  }
  // No git or not a repository: parts 3-5 will say so; the rest still runs.
  return realpathSync(process.cwd());
}

function parseArgs(argv) {
  const excludes = [];
  for (let i = 0; i < argv.length; i += 1) {
    if (argv[i] !== "--orphan-exclude") {
      fail(`unknown argument ${argv[i]}; usage: node verify-ai-context.mjs [--orphan-exclude <path-prefix>]...`);
    }
    const raw = argv[i + 1];
    if (raw === undefined) {
      fail("--orphan-exclude needs a path prefix, e.g. --orphan-exclude tooling/cli/test/fixtures");
    }
    // Normalise the shapes people actually type; reject the ones that can
    // never match a git-tracked path, instead of silently not excluding.
    const value = raw
      .replace(/\\/g, "/")
      .replace(/^(\.\/)+/, "")
      .replace(/\/+$/, "");
    const impossible =
      value === "" ||
      value.startsWith("/") ||
      value.startsWith("-") ||
      /^[A-Za-z]:/.test(value) ||
      value.split("/").includes("..");
    if (impossible) {
      fail(
        `--orphan-exclude must be a repo-relative path prefix, e.g. tooling/cli/test/fixtures; got ${JSON.stringify(raw)}`,
      );
    }
    excludes.push(value);
    i += 1;
  }
  return excludes;
}

function sha256(bytes) {
  return "sha256:" + createHash("sha256").update(bytes).digest("hex");
}

/** A record path must stay repo-relative; anything else means the record was altered. Mirrors the hub's pathProblem. */
function badRecordPath(path) {
  // eslint-disable-next-line no-control-regex -- rejecting control characters is the point
  if (/[\u0000-\u001f\u007f-\u009f]/.test(path)) return true;
  if (path.startsWith("/") || /^[A-Za-z]:/.test(path) || path.includes("\\")) return true;
  return path.split("/").some((part) => part === ".." || part === "." || part === "");
}

/**
 * Constrained parser for the record's hand-rolled YAML, kept in sync with the
 * hub's serializer by a test asserting it parses whatever serializeRecord
 * emits. Quoted values are JSON strings, so JSON.parse is the exact unescape.
 * Unknown fields are ignored, matching gbuddy's tolerant parser: the committed
 * script can be one merge behind a record a newer hub version regenerated.
 */
function parseRecord(document) {
  const marker = document.lastIndexOf("record: ");
  if (marker === -1) throw new Error("the record is missing its integrity line");
  const body = document.slice(0, marker);
  if (sha256(Buffer.from(body, "utf8")) !== document.slice(marker + "record: ".length).trim()) {
    throw new Error("the record integrity check failed (hand edit or merge conflict)");
  }
  const record = { entries: [] };
  const lines = body.split("\n");
  let section = null;
  for (const line of lines) {
    if (line === "" || line.startsWith("#") || line.startsWith("version:")) continue;
    if (line.startsWith("generatedBy: ")) {
      record.generatedBy = jsonToken(line.slice("generatedBy: ".length), line);
      continue;
    }
    if (line === "inputs: []") {
      record.inputs = [];
      continue;
    }
    if (line === "inputs:") {
      record.inputs = [];
      section = "inputs";
      continue;
    }
    if (line === "entries:") {
      section = "entries";
      continue;
    }
    if (section === "inputs" && line.startsWith("  - { path: ")) {
      const input = parseInputLine(line);
      if (input !== null) record.inputs.push(input);
      continue;
    }
    if (section === "entries" && line.startsWith("  - path: ")) {
      record.entries.push({ path: jsonToken(line.slice("  - path: ".length), line) });
      continue;
    }
    if (section === "entries" && line.startsWith("    ")) {
      const entry = record.entries[record.entries.length - 1];
      const [key, value] = splitField(line.trim(), line);
      if (key === "hash" || key === "status" || key === "scope") entry[key] = value;
      continue;
    }
    // An unknown top-level field from a future record shape is not an error.
    if (/^[A-Za-z][A-Za-z0-9]*:/.test(line)) continue;
    throw parseError(line);
  }
  for (const entry of record.entries) {
    if (typeof entry.path !== "string" || typeof entry.hash !== "string") throw parseError(entry.path);
    if (entry.status !== "generated" && entry.status !== "skipped-unmanaged") throw parseError(entry.path);
    if (entry.scope !== "committed" && entry.scope !== "local") throw parseError(entry.path);
  }
  return record;
}

/**
 * One inline input mapping. Exactly one of hash/present must appear (both is
 * the shape the hub parser rejects too); an input carrying neither known field
 * is a future shape this script has no use for and is skipped.
 */
function parseInputLine(line) {
  const rest = line.slice("  - { path: ".length);
  const path = jsonToken(rest, line);
  let tail = rest.slice(JSON.stringify(path).length);
  let hash = null;
  let present = null;
  while (tail !== " }") {
    if (tail.startsWith(', hash: "')) {
      if (hash !== null) throw parseError(line);
      hash = jsonToken(tail.slice(", hash: ".length), line);
      tail = tail.slice(", hash: ".length + JSON.stringify(hash).length);
    } else if (tail.startsWith(", present: true")) {
      if (present !== null) throw parseError(line);
      present = true;
      tail = tail.slice(", present: true".length);
    } else if (tail.startsWith(", present: false")) {
      if (present !== null) throw parseError(line);
      present = false;
      tail = tail.slice(", present: false".length);
    } else {
      const unknown = /^, [A-Za-z][A-Za-z0-9]*: ("(?:[^"\\]|\\.)*"|[^,}]*?)(?=, [A-Za-z]| \})/.exec(tail);
      if (unknown === null) throw parseError(line);
      tail = tail.slice(unknown[0].length);
    }
  }
  if (hash !== null && present !== null) throw parseError(line);
  if (hash !== null) return { path, hash };
  if (present !== null) return { path, present };
  return null;
}

/** Extract one leading JSON string token, escape-aware. */
function jsonToken(text, line) {
  const match = /^"(?:[^"\\]|\\.)*"/.exec(text);
  if (match === null) throw parseError(line);
  return JSON.parse(match[0]);
}

function splitField(trimmed, line) {
  const colon = trimmed.indexOf(": ");
  if (colon === -1) throw parseError(line);
  return [trimmed.slice(0, colon), trimmed.slice(colon + 2)];
}

function parseError(context) {
  return new Error(`the record has an unexpected shape near ${JSON.stringify(String(context))}`);
}

function resolvesInside(repoRoot, absolute) {
  let real;
  try {
    real = realpathSync(absolute);
  } catch {
    return false;
  }
  return real === repoRoot || real.startsWith(repoRoot + sep);
}

/** First bytes of a file; enough for any header, and a header past it fails toward not-ours. */
function headOf(absolute) {
  let fd;
  try {
    fd = openSync(absolute, "r");
  } catch {
    return "";
  }
  try {
    const buffer = Buffer.alloc(4096);
    const length = readSync(fd, buffer, 0, buffer.length, 0);
    return buffer.toString("utf8", 0, length);
  } catch {
    // Unreadable (a directory in a file's place, permissions): not ours.
    return "";
  } finally {
    closeSync(fd);
  }
}

/** Byte-exact header per file type, mirroring the hub's hasProvenanceHeader. */
function hasGeneratedHeader(head) {
  if (head.startsWith(JS_HEADER_PREFIX)) return true;
  let rest = head;
  if (rest.startsWith("---\n")) {
    const close = rest.indexOf("\n---\n", 4);
    if (close === -1) return false;
    rest = rest.slice(close + "\n---\n".length);
    if (rest.startsWith("\n")) rest = rest.slice(1);
  }
  return rest.startsWith(MD_HEADER_PREFIX);
}

/** Tracked paths from git, or null (with the error recorded) when git is unusable. */
function gitTrackedFiles(repoRoot) {
  const result = spawnSync("git", ["ls-files", "-z"], { cwd: repoRoot, maxBuffer: 64 * 1024 * 1024 });
  if (result.error) {
    errors.push("git is required but was not found; cannot verify ignore rules, scopes, or orphans");
    return null;
  }
  if (result.status === 128) {
    errors.push("not a git repository; run the check from inside a git checkout");
    return null;
  }
  if (result.status !== 0) {
    errors.push("git ls-files failed; cannot verify ignore rules, scopes, or orphans");
    return null;
  }
  return new Set(
    result.stdout
      .toString("utf8")
      .split("\0")
      .filter((path) => path !== ""),
  );
}

/** The subset of the given paths an ignore rule matches. check-ignore exits 0 on match, 1 on none, 128 on failure. */
function gitIgnoredAmong(repoRoot, paths) {
  if (paths.length === 0) return [];
  const result = spawnSync("git", ["check-ignore", "--no-index", "-z", "--stdin"], {
    cwd: repoRoot,
    input: Buffer.from(paths.join("\0"), "utf8"),
    maxBuffer: 64 * 1024 * 1024,
  });
  if (result.error || result.status === null || result.status > 1) {
    errors.push("git check-ignore failed; cannot verify ignore rules");
    return [];
  }
  return result.stdout
    .toString("utf8")
    .split("\0")
    .filter((path) => path !== "");
}

/**
 * The manifest's hub pin, or null when the manifest or the field is absent.
 * The same escape guard the inputs get: a manifest resolving outside the
 * repository is never read (its content would otherwise echo into the CI log).
 */
function readPin(repoRoot) {
  const manifestAbsolute = join(repoRoot, MANIFEST_PATH);
  if (!existsSync(manifestAbsolute)) return null;
  if (!resolvesInside(repoRoot, manifestAbsolute)) return null;
  let content;
  try {
    content = readFileSync(manifestAbsolute, "utf8");
  } catch {
    return null;
  }
  const match = /^hub:[ \t]*(.+?)[ \t]*$/m.exec(content);
  if (match === null) return null;
  const raw = match[1];
  const quoted = /^"([^"]*)"/.exec(raw);
  const value = quoted !== null ? quoted[1] : raw.split(/\s#/)[0].trim();
  return value === "" ? null : value;
}

function fail(message) {
  errors.push(message);
  throw ABORT;
}

// process.exitCode, never process.exit: an exit right after console output can
// truncate a pipe, and the exit-code contract is load-bearing for CI.
function report() {
  for (const message of errors) console.error(`error: ${message}`);
  for (const message of warnings) console.warn(`warning: ${message}`);
  if (errors.length > 0) {
    console.error(`verify-ai-context: ${errors.length} problem(s) found`);
    process.exitCode = 1;
    return;
  }
  console.log("verify-ai-context: generated context matches the record");
}
